export service RuntimeContext { static readonly key = "RuntimeContext"; id: string }
export error LinkStoreError { cause: unknown }
export interface Link { readonly code: string }

/** Where links live. The Worker depends on this contract, never on a database. */
export service Links {
  static readonly key = "Links"
  create(url: string): Link!LinkStoreError!RuntimeContext;
  list(): readonly Link[]!LinkStoreError!RuntimeContext;
}
